def compare_versions(a: str, b: str) -> int:
    def parse_version(version_str):
        # Remove build metadata (everything after +)
        version_str = version_str.split('+')[0]

        # Split into core version and pre-release
        if '-' in version_str:
            core, prerelease = version_str.split('-', 1)
            prerelease_ids = prerelease.split('.')
        else:
            core = version_str
            prerelease_ids = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        return (major, minor, patch), prerelease_ids

    def compare_prerelease(pre_a, pre_b):
        # If both have no pre-release, they're equal (in terms of pre-release)
        if pre_a is None and pre_b is None:
            return 0
        # Version without pre-release has higher precedence
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1

        # Both have pre-releases, compare identifiers
        for i in range(max(len(pre_a), len(pre_b))):
            # If one has fewer identifiers, it has lower precedence
            if i >= len(pre_a):
                return -1
            if i >= len(pre_b):
                return 1

            id_a, id_b = pre_a[i], pre_b[i]

            # Check if identifiers are numeric
            is_numeric_a = id_a.isdigit()
            is_numeric_b = id_b.isdigit()

            # Numeric identifiers are compared numerically
            if is_numeric_a and is_numeric_b:
                num_a, num_b = int(id_a), int(id_b)
                if num_a < num_b:
                    return -1
                if num_a > num_b:
                    return 1
            # Numeric identifiers have lower precedence than non-numeric
            elif is_numeric_a:
                return -1
            elif is_numeric_b:
                return 1
            # Non-numeric identifiers are compared lexically
            else:
                if id_a < id_b:
                    return -1
                if id_a > id_b:
                    return 1

        return 0

    core_a, pre_a = parse_version(a)
    core_b, pre_b = parse_version(b)

    # Compare core versions
    if core_a < core_b:
        return -1
    if core_a > core_b:
        return 1

    # Core versions are equal, compare pre-releases
    return compare_prerelease(pre_a, pre_b)

